from pathlib import Path
import subprocess,time,json,tempfile
build=Path('/Volumes/KINGSTON/AIVERSE-builds/building-caverns-gate-build')
root=Path('/Volumes/KINGSTON/AIVERSE-builds/building-caverns-gate-source')
out=build/'stage37-studio/live-owner-stage22'
with tempfile.TemporaryDirectory() as temp:
 port=Path(temp)/'port'
 host=subprocess.Popen([out/'owner',root,str(root/'examples/projectiles'),port])
 try:
  for _ in range(600):
   if port.is_file() and port.read_text().strip():break
   if host.poll() is not None:raise RuntimeError(host.returncode)
   time.sleep(.1)
  portnum=str(int(port.read_text()))
  req=[{'jsonrpc':'2.0','id':1,'method':'initialize','params':{'protocolVersion':'2024-11-05','capabilities':{},'clientInfo':{'name':'owner-check','version':'1'}}},{'jsonrpc':'2.0','method':'notifications/initialized','params':{}}]
  for i,scene in enumerate(['1','2','999'],2):
   req.append({'jsonrpc':'2.0','id':i,'method':'tools/call','params':{'name':'building_graph_diagnostics','arguments':{'sceneId':scene}}})
  result=subprocess.run([build/'aiversemcp','--engine',root,'--port',portnum],input=''.join(json.dumps(x)+'\n' for x in req),capture_output=True,text=True,timeout=35,check=True)
  data={x['id']:x for x in (json.loads(line) for line in result.stdout.splitlines()) if 'id' in x}
  reports=[json.loads(data[i]['result']['content'][0]['text']) for i in (2,3,4)]
  (out/'diagnostics.json').write_text(json.dumps(reports,indent=2))
  for r in reports[:2]:
   assert r['available'],r
   assert r['snapshot']['ownerTelemetry']['navmesh']['tileCount']>0,r
  assert reports[2]['available'] is False,reports[2]
  print('PASS two live scenes with native navigation telemetry; absent scene unavailable')
 finally:
  host.terminate();host.wait(timeout=10)
